{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/comparison-table.json
    Plans, or a product and its competitors, as three columns and the features as rows. A value of yes shows a check, no a dash (both with a hidden word), anything else is shown as text. Axes: highlight (none, middle column), tone, density.
    Props (p): id, title, rows, labels, highlight, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_rows = ($p['rows'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_highlight = ($p['highlight'] ?? 'none')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_16}
  {capture $c_15}
    {capture $c_14}
      {capture $c_1}
        {=ui_text(ui_get($v_labels, ['caption']))}
      {/capture}
      {=ui_include('ui/table/table-caption.latte', ['p' => ['Class' => 'sr-only'], 'children' => $c_1])|noescape}
      {capture $c_7}
        {capture $c_6}
          {capture $c_2}
            {=ui_text(ui_get($v_labels, ['feature']))}
          {/capture}
          {=ui_include('ui/table/table-head-cell.latte', ['p' => ['Scope' => 'col', 'Class' => 'py-4'], 'children' => $c_2])|noescape}
          {capture $c_3}
            {=ui_text(ui_get($v_labels, ['a']))}
          {/capture}
          {=ui_include('ui/table/table-head-cell.latte', ['p' => ['Scope' => 'col', 'Class' => 'py-4'], 'children' => $c_3])|noescape}
          {capture $c_4}
            {=ui_text(ui_get($v_labels, ['b']))}
          {/capture}
          {=ui_include('ui/table/table-head-cell.latte', ['p' => ['Scope' => 'col', 'Class' => ui_s(ui_cnv(['py-4', (ui_t(ui_eq($v_highlight, 'middle')) ? 'bg-muted' : '')])), 'Attrs' => ui_attrs(['data-highlight', (ui_t(ui_eq($v_highlight, 'middle')) ? 'true' : 'false')])], 'children' => $c_4])|noescape}
          {capture $c_5}
            {=ui_text(ui_get($v_labels, ['c']))}
          {/capture}
          {=ui_include('ui/table/table-head-cell.latte', ['p' => ['Scope' => 'col', 'Class' => 'py-4'], 'children' => $c_5])|noescape}
        {/capture}
        {=ui_include('ui/table/table-row.latte', ['p' => [], 'children' => $c_6])|noescape}
      {/capture}
      {=ui_include('ui/table/table-head.latte', ['p' => [], 'children' => $c_7])|noescape}
      {capture $c_13}
        {foreach ui_l($v_rows) as $v_row}
          {capture $c_12}
            {capture $c_8}
              {=ui_text(ui_get($v_row, ['label']))}
            {/capture}
            {=ui_include('ui/table/table-head-cell.latte', ['p' => ['Scope' => 'row', 'Class' => ui_s(ui_cnv(['font-medium', (ui_t(ui_eq($v_density, 'compact')) ? 'py-2' : 'py-4')]))], 'children' => $c_8])|noescape}
            {capture $c_9}
              {=ui_include('blocks/compare-mark.latte', ['p' => ['value' => ui_get($v_row, ['a']), 'yes' => ui_get($v_labels, ['yes']), 'no' => ui_get($v_labels, ['no'])]])|noescape}
            {/capture}
            {=ui_include('ui/table/table-cell.latte', ['p' => ['Class' => ui_s(ui_cnv([(ui_t(ui_eq($v_density, 'compact')) ? 'py-2' : 'py-4')]))], 'children' => $c_9])|noescape}
            {capture $c_10}
              {=ui_include('blocks/compare-mark.latte', ['p' => ['value' => ui_get($v_row, ['b']), 'yes' => ui_get($v_labels, ['yes']), 'no' => ui_get($v_labels, ['no'])]])|noescape}
            {/capture}
            {=ui_include('ui/table/table-cell.latte', ['p' => ['Class' => ui_s(ui_cnv([(ui_t(ui_eq($v_density, 'compact')) ? 'py-2' : 'py-4'), (ui_t(ui_eq($v_highlight, 'middle')) ? 'bg-muted font-semibold' : '')]))], 'children' => $c_10])|noescape}
            {capture $c_11}
              {=ui_include('blocks/compare-mark.latte', ['p' => ['value' => ui_get($v_row, ['c']), 'yes' => ui_get($v_labels, ['yes']), 'no' => ui_get($v_labels, ['no'])]])|noescape}
            {/capture}
            {=ui_include('ui/table/table-cell.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_density, 'compact')) ? 'py-2' : 'py-4'))], 'children' => $c_11])|noescape}
          {/capture}
          {=ui_include('ui/table/table-row.latte', ['p' => ['Class' => 'border-t border-border', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_12])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/table/table-body.latte', ['p' => [], 'children' => $c_13])|noescape}
    {/capture}
    {=ui_include('ui/table/table.latte', ['p' => ['Class' => 'w-full text-left text-sm', 'Attrs' => ui_attrs(['data-testid', 'compare'])], 'children' => $c_14])|noescape}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'relative w-full overflow-x-auto'], 'children' => $c_15])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_16])|noescape}
